begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) select ('20000000-0000-0000-0000-00000000000'||n)::uuid,'manual-test-'||n||'@example.invalid',jsonb_build_object('username','ManualTest'||n) from generate_series(1,4) n;
insert into auth.sessions(id,user_id) select id,id from public.profiles where id::text like '20000000-%';
update private.authz set role='critic' where user_id='20000000-0000-0000-0000-000000000002';
update private.authz set role='moderator' where user_id='20000000-0000-0000-0000-000000000003';
update private.authz set role='admin' where user_id='20000000-0000-0000-0000-000000000004';
create temp table manual_input(data jsonb);
insert into manual_input values ('{"title":"Isolated adversarial fixture","synopsis":"Isolated SQL test fixture, never real catalog data.","platforms":["PC"],"genres":["Test"],"releasedAt":null,"sourceUrl":"https://example.com/isolated-gh018-sql-fixture","sourceLabel":"Isolated fixture","reason":"Isolated SQL acceptance test"}');
select is(private.manual_source('https://WWW.CELESTEGAME.COM:443/#x'),'https://www.celestegame.com/','canonical host port fragment');
select is(private.manual_source('https://example.com/game?a=2#x'),'https://example.com/game?a=2','preserve query and path');
select throws_ok($$select private.manual_source('http://example.com')$$,'22023',null,'unsafe URL rejected');
select throws_ok($$select private.manual_source('javascript:alert(1)')$$,'22023',null,'unsafe URL rejected');
select throws_ok($$select private.manual_source('https://a:b@example.com')$$,'22023',null,'unsafe URL rejected');
select throws_ok($$select private.manual_source('https://localhost')$$,'22023',null,'unsafe URL rejected');
select throws_ok($$select private.manual_source('https://127.0.0.1')$$,'22023',null,'unsafe URL rejected');
select throws_ok($$select private.manual_source('https://[::1]')$$,'22023',null,'unsafe URL rejected');
select throws_ok($$select private.manual_source('https://2130706433')$$,'22023',null,'unsafe URL rejected');
select throws_ok($$select private.manual_source('https://a.local')$$,'22023',null,'unsafe URL rejected');
select throws_ok($$select private.manual_source('https://example.com:99999/')$$,'22023',null,'unsafe URL rejected');
select throws_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001',data) from manual_input$$,'42501',null,'role 1 cannot create');
select throws_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000002',data) from manual_input$$,'42501',null,'role 2 cannot create');
select throws_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000003',data) from manual_input$$,'42501',null,'role 3 cannot create');
select lives_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000004',data) from manual_input$$,'admin creates');
select is((select count(*)::int from public.manual_games where title='Isolated adversarial fixture'),1,'one persisted game');
select is((select count(*)::int from private.audit_logs where action='manual_game.create' and actor_id='20000000-0000-0000-0000-000000000004'),1,'one audit');
select ok((select target_id is null and after_data->>'gameId' like 'manual:%' from private.audit_logs where action='manual_game.create' and actor_id='20000000-0000-0000-0000-000000000004'),'game identifier in private audit');
select throws_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000004',data) from manual_input$$,'23505',null,'duplicate canonical source');
select is((select count(*)::int from private.audit_logs where action='manual_game.create' and actor_id='20000000-0000-0000-0000-000000000004'),1,'no duplicate audit');
select throws_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000004',data||jsonb_build_object('sourceUrl','https://example.com/isolated-gh018-negative-1')||'{"title":"<b>test</b>"}'::jsonb) from manual_input$$,'22023',null,'invalid input 1 rejected with exact SQLSTATE');
select throws_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000004',data||jsonb_build_object('sourceUrl','https://example.com/isolated-gh018-negative-2')||'{"genres":["<b>RPG</b>"]}'::jsonb) from manual_input$$,'22023',null,'invalid input 2 rejected with exact SQLSTATE');
select throws_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000004',data||jsonb_build_object('sourceUrl','https://example.com/isolated-gh018-negative-3')||'{"reason":"short"}'::jsonb) from manual_input$$,'22023',null,'invalid input 3 rejected with exact SQLSTATE');
select throws_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000004',data||jsonb_build_object('sourceUrl','https://example.com/isolated-gh018-negative-4')||'{"platforms":[]}'::jsonb) from manual_input$$,'22023',null,'invalid input 4 rejected with exact SQLSTATE');
select throws_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000004',data||jsonb_build_object('sourceUrl','https://example.com/isolated-gh018-negative-5')||'{"releasedAt":"2026-02-30"}'::jsonb) from manual_input$$,'22008',null,'invalid input 5 rejected with exact SQLSTATE');
select throws_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000004',data||jsonb_build_object('sourceUrl','https://example.com/isolated-gh018-negative-6')||'{"genres":[null]}'::jsonb) from manual_input$$,'22023',null,'invalid input 6 rejected with exact SQLSTATE');
update private.authz set status='suspended' where user_id='20000000-0000-0000-0000-000000000004';
select throws_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000004',data) from manual_input$$,'42501',null,'suspended admin rejected');
update private.authz set status='active' where user_id='20000000-0000-0000-0000-000000000004';
delete from auth.sessions where id='20000000-0000-0000-0000-000000000004';
select throws_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000004',data) from manual_input$$,'42501',null,'revoked session rejected');
insert into auth.sessions(id,user_id) values('20000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000004');
create function pg_temp.fail_manual_audit() returns trigger language plpgsql as $$begin raise exception 'Injected isolated audit failure'; end;$$;
create trigger isolated_manual_audit_failure before insert on private.audit_logs for each row execute function pg_temp.fail_manual_audit();
select throws_ok($$select private.create_manual_game('20000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000004',data||'{"sourceUrl":"https://example.com/other"}') from manual_input$$,'P0001',null,'audit failure aborts transaction');
select is((select count(*)::int from public.manual_games where title='Isolated adversarial fixture'),1,'audit failure leaves no partial game');
drop trigger isolated_manual_audit_failure on private.audit_logs;
set local role anon;
select is((select count(*)::int from public.manual_games where title='Isolated adversarial fixture'),1,'public read');
select throws_ok($$insert into public.manual_games(title) values('forged')$$,'42501',null,'Data API cannot write or invoke');
select throws_ok($$update public.manual_games set title='forged'$$,'42501',null,'Data API cannot write or invoke');
select throws_ok($$delete from public.manual_games$$,'42501',null,'Data API cannot write or invoke');
select throws_ok($$select private.create_manual_game(null,null,'{}')$$,'42501',null,'Data API cannot write or invoke');
reset role;
set local role authenticated;
select is((select count(*)::int from public.manual_games where title='Isolated adversarial fixture'),1,'public read');
select throws_ok($$insert into public.manual_games(title) values('forged')$$,'42501',null,'Data API cannot write or invoke');
select throws_ok($$update public.manual_games set title='forged'$$,'42501',null,'Data API cannot write or invoke');
select throws_ok($$delete from public.manual_games$$,'42501',null,'Data API cannot write or invoke');
select throws_ok($$select private.create_manual_game(null,null,'{}')$$,'42501',null,'Data API cannot write or invoke');
reset role;
set local role service_role;
select throws_ok($$insert into public.manual_games(title) values('forged')$$,'42501',null,'Data API cannot write or invoke');
select throws_ok($$update public.manual_games set title='forged'$$,'42501',null,'Data API cannot write or invoke');
select throws_ok($$delete from public.manual_games$$,'42501',null,'Data API cannot write or invoke');
select throws_ok($$select private.create_manual_game(null,null,'{}')$$,'42501',null,'Data API cannot write or invoke');
reset role;
select * from finish();
rollback;
